        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1AgentRoutinesRunsRunJournal.Params{}
      ) do
    path = "/api/v1/agent_routines/runs/#{ArchAstro.SDK.Path.encode(run)}/journal"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.RunJournalPage}
    )
  end
end
